# Pure policy helper so timing/sequence correctness is unit-testable without Android runtime.
policy = root / 'app/src/main/java/com/yagay/nfcdoorcard/xposed/RfSettlingPolicy.java'
policy.write_text('''package com.yagay.nfcdoorcard.xposed;\n\n/** Pure lifecycle settling rules used by the NFC process hook. */\npublic final class RfSettlingPolicy {\n    private RfSettlingPolicy() {}\n\n    public static boolean isSettled(long now, long recoveryStartedAt, long lastRfWriteAt,\n                                    long minSettleMs, long quietMs) {\n        if (recoveryStartedAt <= 0L || now < recoveryStartedAt) return false;\n        if (now - recoveryStartedAt < Math.max(0L, minSettleMs)) return false;\n        if (lastRfWriteAt <= 0L) return true;\n        if (now < lastRfWriteAt) return false;\n        return now - lastRfWriteAt >= Math.max(0L, quietMs);\n    }\n\n    public static boolean isStrictlyNewer(long sequence, long baseline) {\n        return sequence > baseline && sequence > 0L;\n    }\n}\n''')

test = root / 'app/src/test/java/com/yagay/nfcdoorcard/xposed/RfSettlingPolicyTest.java'
test.parent.mkdir(parents=True, exist_ok=True)
test.write_text('''package com.yagay.nfcdoorcard.xposed;\n\nimport static org.junit.Assert.assertFalse;\nimport static org.junit.Assert.assertTrue;\n\nimport org.junit.Test;\n\npublic class RfSettlingPolicyTest {\n    @Test public void requiresMinimumStartupSettleTime() {\n        assertFalse(RfSettlingPolicy.isSettled(1_900L, 1_000L, 1_100L, 1_200L, 700L));\n        assertTrue(RfSettlingPolicy.isSettled(2_200L, 1_000L, 1_100L, 1_200L, 700L));\n    }\n\n    @Test public void requiresQuietPeriodAfterLateRfWrite() {\n        assertFalse(RfSettlingPolicy.isSettled(3_000L, 1_000L, 2_600L, 1_200L, 700L));\n        assertTrue(RfSettlingPolicy.isSettled(3_300L, 1_000L, 2_600L, 1_200L, 700L));\n    }\n\n    @Test public void noObservedWriteCanSettleAfterMinimumWindow() {\n        assertTrue(RfSettlingPolicy.isSettled(2_500L, 1_000L, 0L, 1_200L, 700L));\n    }\n\n    @Test public void finalProofRequiresStrictlyNewSequence() {\n        assertFalse(RfSettlingPolicy.isStrictlyNewer(5L, 5L));\n        assertFalse(RfSettlingPolicy.isStrictlyNewer(4L, 5L));\n        assertTrue(RfSettlingPolicy.isStrictlyNewer(6L, 5L));\n    }\n}\n''')

print('RF final settling migration applied')
